const source = fs.readFileSync(".github/workflows/native-windows.yml", "utf8");
describe("actual native workflow", () => {
  it("retains read-only exact locks, full audit, clean package, extracted consumer and small evidence", () => {
    expect(() => policy(source)).not.toThrow();
  });
  it.each([
    ["broad write permission", "contents: read", "contents: write"],
    ["wrong source event", "pull_request:", "pull_request_target:"],
    ["omitted original unit gate", "run: pnpm test", "run: echo skipped"],
    ["omitted audit", "npm audit --prefix desktop --audit-level moderate", "echo no-audit"],
    [
      "dirty release candidate",
      "node tools/package-native.mjs release/ci-portable",
      "node tools/package-native.mjs release/ci-portable --allow-dirty",
    ],
    [
      "source instead of compiled consumer",
      ".runtime/relocated-portable/KnowledgePortal.exe",
      "desktop/main.mjs",
    ],
    ["unverified archive", "$sidecar -cne", "$sidecar -ceq"],
    ["profile upload", ".runtime/ci-acceptance/native-*.png", ".runtime/ci-acceptance/**"],
    ["long retention", "retention-days: 3", "retention-days: 90"],
  ])("refuses %s", (_name, from, to) => {
    expect(source).toContain(from);
    expect(() => policy(source.replace(from, to))).toThrow();
  });
  it("rejects duplicate permission declarations before interpretation", () => {
    expect(() =>
      policy(source.replace("  contents: read", "  contents: read\n  contents: write")),
    ).toThrow(/Ambiguous/u);
  });
});
